import { useTooltip } from './useTooltip.js';
//TODO ADES-4832 move to common meter-bar folder and reuse across meter and multimeter
export const useSegmentHandlers = () => {
  const {
    hideTooltipHandler,
    showTooltipHandler,
    toggleTooltipPinnedStateHandler,
    updateTooltipContentHandler,
  } = useTooltip();

  const handleSegmentMouseClick = (event: React.MouseEvent, id?: string) => {
    event.stopPropagation();

    toggleTooltipPinnedStateHandler();
    id && updateTooltipContentHandler(id);
  };

  const handleSegmentMouseEnter = (id: string) => {
    updateTooltipContentHandler(id);
    showTooltipHandler();
  };

  const handleSegmentMouseLeave = () => {
    hideTooltipHandler();
  };

  const handleSegmentMouseMove = () => {
    showTooltipHandler();
  };

  return {
    handleSegmentMouseClick,
    handleSegmentMouseEnter,
    handleSegmentMouseLeave,
    handleSegmentMouseMove,
  };
};
